# Identify the learning paradigm
scenarios = [
    "Chess AI learns by playing games",
    "Grouping customers by purchase patterns",
    "Email spam detector trained on labeled emails",
]
for scenario in scenarios:
    if "labeled" in scenario:
        print(f"{scenario}: supervised")
    elif "grouping" in scenario.lower():
        print(f"{scenario}: unsupervised")
    else:
        print(f"{scenario}: reinforcement")

